from datetime import datetime, timedelta

import pytest
from isoduration import add_duration


class TestSyntaxValidation:
    """Test parsing and validation of ISO 8601 duration strings."""

    # Valid basic components
    def test_years_only(self):
        assert add_duration(datetime(2025, 3, 10), "P1Y") == datetime(2026, 3, 10)

    def test_months_only(self):
        assert add_duration(datetime(2025, 3, 10), "P2M") == datetime(2025, 5, 10)

    def test_weeks_only(self):
        assert add_duration(datetime(2025, 3, 10), "P2W") == datetime(2025, 3, 24)

    def test_days_only(self):
        assert add_duration(datetime(2025, 3, 10), "P3D") == datetime(2025, 3, 13)

    def test_hours_only(self):
        assert add_duration(datetime(2025, 3, 10, 8, 0), "PT1H") == datetime(2025, 3, 10, 9, 0)

    def test_minutes_only(self):
        assert add_duration(datetime(2025, 3, 10, 8, 0), "PT30M") == datetime(2025, 3, 10, 8, 30)

    def test_seconds_only(self):
        assert add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT45S") == datetime(2025, 3, 10, 8, 0, 45)

    # Valid combinations
    def test_years_and_months(self):
        assert add_duration(datetime(2025, 3, 10), "P1Y2M") == datetime(2026, 5, 10)

    def test_days_and_time(self):
        assert add_duration(datetime(2025, 3, 10, 8), "P3DT2H30M") == datetime(2025, 3, 13, 10, 30)

    def test_all_components(self):
        assert add_duration(datetime(2025, 3, 10, 8), "P1Y2M10DT2H30M") == datetime(2026, 5, 20, 10, 30)

    def test_all_components_with_seconds(self):
        assert add_duration(datetime(2025, 3, 10, 8, 0, 0), "P1Y2M10DT2H30M15S") == datetime(2026, 5, 20, 10, 30, 15)

    # Sign handling
    def test_explicit_positive_sign(self):
        assert add_duration(datetime(2025, 3, 10), "+P1D") == datetime(2025, 3, 11)

    def test_negative_sign(self):
        assert add_duration(datetime(2025, 3, 10), "-P1D") == datetime(2025, 3, 9)

    # Fractional parts
    def test_fractional_seconds_dot(self):
        result = add_duration(datetime(2025, 3, 10), "PT1.5S")
        assert result == datetime(2025, 3, 10, 0, 0, 1, 500000)

    def test_fractional_seconds_comma(self):
        result = add_duration(datetime(2025, 3, 10), "PT1,5S")
        assert result == datetime(2025, 3, 10, 0, 0, 1, 500000)

    def test_fractional_minutes(self):
        result = add_duration(datetime(2025, 3, 10), "PT1.5M")
        assert result == datetime(2025, 3, 10, 0, 1, 30)

    def test_fractional_hours(self):
        result = add_duration(datetime(2025, 3, 10), "PT1.5H")
        assert result == datetime(2025, 3, 10, 1, 30)

    def test_fractional_days(self):
        result = add_duration(datetime(2025, 3, 10), "P1.5D")
        assert result == datetime(2025, 3, 11, 12, 0)

    def test_fractional_weeks(self):
        result = add_duration(datetime(2025, 3, 10), "P1.5W")
        assert result == datetime(2025, 3, 24, 12, 0)

    # Leading zeros
    def test_leading_zeros_in_components(self):
        assert add_duration(datetime(2025, 3, 10), "P01Y02M") == datetime(2026, 5, 10)

    def test_leading_zeros_in_fractional(self):
        result = add_duration(datetime(2025, 3, 10), "PT0.5S")
        assert result == datetime(2025, 3, 10, 0, 0, 0, 500000)

    # Invalid syntax - must raise ValueError
    def test_invalid_missing_p(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "1D")

    def test_invalid_p_only(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P")

    def test_invalid_pt_only(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT")

    def test_invalid_p_followed_by_t_no_time(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1DT")

    def test_invalid_weeks_with_days(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P2W3D")

    def test_invalid_weeks_with_months(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1M2W")

    def test_invalid_duplicate_component_days(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1D2D")

    def test_invalid_duplicate_component_months(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1M2M")

    def test_invalid_component_order_months_after_days(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1D2M")

    def test_invalid_component_order_time_before_date(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT1H2D")

    def test_invalid_months_after_t(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1DT1M2M")

    def test_invalid_fraction_on_years(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1.5Y")

    def test_invalid_fraction_on_months(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1.5M")

    def test_invalid_multiple_fractions(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1.5D2.5H")

    def test_invalid_fraction_missing_digit_before_dot(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT.5S")

    def test_invalid_fraction_missing_digit_after_dot(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT1.S")

    def test_invalid_whitespace(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P 1D")

    def test_invalid_sign_on_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P-1D")

    def test_invalid_lowercase_p(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "p1D")

    def test_invalid_lowercase_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1d")

    def test_invalid_lowercase_t(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1Dt1H")

    def test_invalid_empty_string(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "")

    def test_invalid_no_component_values(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PYMDTHMS")

    def test_invalid_non_digit_in_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1aD")

    def test_invalid_multiple_decimal_points(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT1.2.3S")


class TestMonthApplication:
    """Test year and month addition, including month overflow handling."""

    def test_add_month_no_overflow(self):
        assert add_duration(datetime(2025, 1, 15), "P1M") == datetime(2025, 2, 15)

    def test_add_12_months(self):
        assert add_duration(datetime(2025, 3, 10), "P12M") == datetime(2026, 3, 10)

    def test_add_year(self):
        assert add_duration(datetime(2025, 3, 10), "P1Y") == datetime(2026, 3, 10)

    def test_add_year_and_month(self):
        assert add_duration(datetime(2025, 3, 10), "P1Y1M") == datetime(2026, 4, 10)

    def test_month_overflow_31_to_28(self):
        # Jan 31 + 1 month = Feb 28 (non-leap year)
        assert add_duration(datetime(2025, 1, 31), "P1M") == datetime(2025, 2, 28)

    def test_month_overflow_31_to_29_leap_year(self):
        # Jan 31, 2024 (leap year) + 1 month = Feb 29
        assert add_duration(datetime(2024, 1, 31), "P1M") == datetime(2024, 2, 29)

    def test_month_overflow_31_to_30(self):
        # May 31 + 1 month = June 30
        assert add_duration(datetime(2025, 5, 31), "P1M") == datetime(2025, 6, 30)

    def test_month_overflow_multiple_months(self):
        # Jan 31, 2024 + 13 months = Feb 29, 2025 (13 months applied together)
        assert add_duration(datetime(2024, 1, 31), "P1Y1M") == datetime(2025, 2, 28)

    def test_negative_month(self):
        assert add_duration(datetime(2025, 3, 10), "-P1M") == datetime(2025, 2, 10)

    def test_negative_month_with_overflow(self):
        # Mar 31 - 1 month = Feb 28
        assert add_duration(datetime(2025, 3, 31), "-P1M") == datetime(2025, 2, 28)

    def test_negative_multiple_months(self):
        # 2025-03-01 - P1M1D = 2024-01-31 (first back 1 month to 2025-02-01, then back 1 day)
        assert add_duration(datetime(2025, 3, 1), "-P1M1D") == datetime(2025, 1, 31)

    def test_add_many_years(self):
        assert add_duration(datetime(2025, 3, 10), "P10Y") == datetime(2035, 3, 10)

    def test_leap_year_feb_29_plus_year(self):
        # 2024-02-29 + 1 year = 2025-02-28 (non-leap year)
        assert add_duration(datetime(2024, 2, 29), "P1Y") == datetime(2025, 2, 28)

    def test_leap_year_feb_29_plus_4_years(self):
        # 2024-02-29 + 4 years = 2028-02-29 (another leap year)
        assert add_duration(datetime(2024, 2, 29), "P4Y") == datetime(2028, 2, 29)

    def test_months_as_multiples_of_12(self):
        # P2M applied to same day in 2 different months
        result1 = add_duration(datetime(2025, 1, 15), "P2M")
        result2 = add_duration(datetime(2025, 2, 15), "P1M")
        assert result1 == datetime(2025, 3, 15)
        assert result2 == datetime(2025, 3, 15)


class TestDayApplication:
    """Test week and day addition."""

    def test_add_1_week(self):
        assert add_duration(datetime(2025, 3, 10), "P1W") == datetime(2025, 3, 17)

    def test_add_multiple_weeks(self):
        assert add_duration(datetime(2025, 3, 10), "P3W") == datetime(2025, 3, 31)

    def test_add_days_across_month_boundary(self):
        assert add_duration(datetime(2025, 3, 30), "P5D") == datetime(2025, 4, 4)

    def test_add_days_across_year_boundary(self):
        assert add_duration(datetime(2025, 12, 28), "P5D") == datetime(2026, 1, 2)

    def test_negative_days(self):
        assert add_duration(datetime(2025, 3, 10), "-P3D") == datetime(2025, 3, 7)

    def test_negative_weeks(self):
        assert add_duration(datetime(2025, 3, 10), "-P2W") == datetime(2025, 2, 24)

    def test_negative_days_across_month_boundary(self):
        assert add_duration(datetime(2025, 3, 5), "-P10D") == datetime(2025, 2, 23)

    def test_fractional_days_as_hours(self):
        # P0.5D = 12 hours
        result = add_duration(datetime(2025, 3, 10), "P0.5D")
        assert result == datetime(2025, 3, 10, 12, 0)

    def test_fractional_weeks_as_days_and_hours(self):
        # P0.5W = 3.5 days = 3 days + 12 hours
        result = add_duration(datetime(2025, 3, 10), "P0.5W")
        assert result == datetime(2025, 3, 13, 12, 0)

    def test_very_large_day_addition(self):
        result = add_duration(datetime(2025, 1, 1), "P365D")
        assert result == datetime(2026, 1, 1)

    def test_days_and_weeks_combined(self):
        # Week is exactly 7 days
        result1 = add_duration(datetime(2025, 3, 10), "P1W3D")
        # This should be invalid - weeks cannot be combined with other components
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1W3D")


class TestTimeApplication:
    """Test hour, minute, and second addition."""

    def test_add_hours(self):
        assert add_duration(datetime(2025, 3, 10, 8), "PT1H") == datetime(2025, 3, 10, 9)

    def test_add_minutes(self):
        assert add_duration(datetime(2025, 3, 10, 8, 30), "PT30M") == datetime(2025, 3, 10, 9, 0)

    def test_add_seconds(self):
        assert add_duration(datetime(2025, 3, 10, 8, 0, 30), "PT30S") == datetime(2025, 3, 10, 8, 1, 0)

    def test_add_time_across_day_boundary(self):
        result = add_duration(datetime(2025, 3, 10, 23, 30), "PT1H")
        assert result == datetime(2025, 3, 11, 0, 30)

    def test_add_time_across_year_boundary(self):
        result = add_duration(datetime(2025, 12, 31, 23), "PT1H")
        assert result == datetime(2026, 1, 1, 0)

    def test_negative_hours(self):
        assert add_duration(datetime(2025, 3, 10, 8), "-PT1H") == datetime(2025, 3, 10, 7)

    def test_negative_time_across_day_boundary(self):
        result = add_duration(datetime(2025, 3, 11, 0, 30), "-PT1H")
        assert result == datetime(2025, 3, 10, 23, 30)

    def test_fractional_hours_as_minutes(self):
        # PT0.5H = 30 minutes
        result = add_duration(datetime(2025, 3, 10, 8), "PT0.5H")
        assert result == datetime(2025, 3, 10, 8, 30)

    def test_fractional_minutes_as_seconds(self):
        # PT0.5M = 30 seconds
        result = add_duration(datetime(2025, 3, 10, 8, 0), "PT0.5M")
        assert result == datetime(2025, 3, 10, 8, 0, 30)

    def test_fractional_seconds_with_microseconds(self):
        # PT0.5S = 500000 microseconds
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT0.5S")
        assert result == datetime(2025, 3, 10, 8, 0, 0, 500000)

    def test_very_small_fractional_seconds(self):
        # PT0.001S = 1000 microseconds
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT0.001S")
        assert result == datetime(2025, 3, 10, 8, 0, 0, 1000)

    def test_microsecond_precision(self):
        # PT0.0000001S should round to nearest microsecond
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT0.0000001S")
        # 0.0000001 seconds = 0.1 microseconds, rounds to 0
        assert result == datetime(2025, 3, 10, 8, 0, 0, 0)

    def test_microsecond_rounding_up(self):
        # PT0.0000005S should round to 1 microsecond (banker's rounding)
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT0.0000005S")
        # 0.0000005 seconds = 0.5 microseconds
        # Using Python's round() which does banker's rounding
        assert result.microsecond in [0, 1]  # Banker's rounding

    def test_time_with_microseconds_addition(self):
        # Adding fractional time to a datetime with microseconds
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0, 100000), "PT0.4S")
        # 0.4S = 400000 microseconds, 100000 + 400000 = 500000
        assert result == datetime(2025, 3, 10, 8, 0, 0, 500000)

    def test_combined_time_components(self):
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT1H30M45S")
        assert result == datetime(2025, 3, 10, 9, 30, 45)


class TestApplicationOrder:
    """Test that components are applied in the correct order."""

    def test_months_then_days(self):
        # 2024-01-31 + P1M (to 2024-02-29) + P1D = 2024-03-01
        result = add_duration(datetime(2024, 1, 31), "P1M1D")
        assert result == datetime(2024, 3, 1)

    def test_months_then_time(self):
        # Time components preserve hours/minutes/seconds
        result = add_duration(datetime(2025, 3, 10, 8, 30, 15), "P1M")
        assert result == datetime(2025, 4, 10, 8, 30, 15)

    def test_full_combination(self):
        # P1Y2M10DT2H30M applied in order
        result = add_duration(datetime(2025, 3, 10, 8, 0), "P1Y2M10DT2H30M")
        assert result == datetime(2026, 5, 20, 10, 30)

    def test_negative_multiple_components(self):
        # 2025-03-01 - P1M1D = 2025-02-01 - 1D = 2025-01-31
        result = add_duration(datetime(2025, 3, 1), "-P1M1D")
        assert result == datetime(2025, 1, 31)

    def test_negative_with_month_and_time(self):
        # 2025-03-15 08:00:00 - P1M1H = 2025-02-15 07:00:00
        result = add_duration(datetime(2025, 3, 15, 8, 0, 0), "-P1M1H")
        assert result == datetime(2025, 2, 15, 7, 0, 0)

    def test_zero_months_applied_then_days(self):
        # Even with zero months, day calculation should work
        result = add_duration(datetime(2025, 3, 10), "P10D")
        assert result == datetime(2025, 3, 20)

    def test_time_applied_last(self):
        # Verify that time is applied after date changes
        result = add_duration(datetime(2025, 3, 10, 23, 0), "P1DT1H")
        assert result == datetime(2025, 3, 12, 0, 0)


class TestEdgeCases:
    """Test edge cases and boundary conditions."""

    def test_zero_duration_components(self):
        # P0D should not change anything
        result = add_duration(datetime(2025, 3, 10), "P0D")
        assert result == datetime(2025, 3, 10)

    def test_all_zero_components(self):
        result = add_duration(datetime(2025, 3, 10), "P0Y0M0D")
        # This should be valid but might be invalid per spec - depends on interpretation
        # If spec says "at least one component required", this might be invalid
        # Let me check the spec again - it says "at least one component is required"
        # So P0D should be valid (one component with value 0)
        assert result == datetime(2025, 3, 10)

    def test_datetime_min_plus_duration(self):
        # datetime.min + something small
        result = add_duration(datetime.min, "P1D")
        expected = datetime.min + timedelta(days=1)
        assert result == expected

    def test_datetime_max_minus_duration(self):
        # datetime.max - something small
        result = add_duration(datetime.max, "-P1D")
        expected = datetime.max - timedelta(days=1)
        assert result == expected

    def test_datetime_min_plus_large_duration_overflow(self):
        # Adding a large enough duration from min should work
        result = add_duration(datetime(1, 1, 1), "P9998Y")
        assert result == datetime(9999, 1, 1)

    def test_datetime_max_minus_large_duration_underflow(self):
        # Subtracting a large duration should work
        result = add_duration(datetime(9999, 12, 31), "-P9998Y")
        assert result == datetime(1, 12, 31)

    def test_duration_exceeds_max_raises_error(self):
        # Adding more than available should raise ValueError
        with pytest.raises(ValueError):
            add_duration(datetime(9999, 12, 31), "P1D")

    def test_duration_exceeds_min_raises_error(self):
        # Subtracting more than available should raise ValueError
        with pytest.raises(ValueError):
            add_duration(datetime(1, 1, 1), "-P1D")

    def test_very_large_fractional_seconds(self):
        # Many fractional digits
        result = add_duration(datetime(2025, 3, 10), "PT0.123456S")
        # 0.123456 seconds = 123456 microseconds
        assert result == datetime(2025, 3, 10, 0, 0, 0, 123456)

    def test_fractional_zero(self):
        result = add_duration(datetime(2025, 3, 10), "PT0.0S")
        assert result == datetime(2025, 3, 10)

    def test_large_number_components(self):
        # Large but reasonable component values
        result = add_duration(datetime(2025, 1, 1), "P100Y")
        assert result == datetime(2125, 1, 1)

    def test_combination_with_zero_months(self):
        result = add_duration(datetime(2025, 3, 10), "P0M10D")
        assert result == datetime(2025, 3, 20)

    def test_combination_with_zero_days(self):
        result = add_duration(datetime(2025, 3, 10), "P1M0D")
        assert result == datetime(2025, 4, 10)

    def test_february_edge_cases(self):
        # Feb 28 + 1 month in non-leap year
        result = add_duration(datetime(2025, 2, 28), "P1M")
        assert result == datetime(2025, 3, 28)

    def test_december_to_january(self):
        result = add_duration(datetime(2025, 12, 1), "P1M")
        assert result == datetime(2026, 1, 1)

    def test_first_to_last_of_month(self):
        result = add_duration(datetime(2025, 1, 1), "P1M")
        assert result == datetime(2025, 2, 1)

    def test_end_of_month_preservation(self):
        # Jan 31 + 2M + 2M = Mar 29 (Feb overflow to 28) + 2M = May 29 (Apr has 30)
        # Actually: 2025-01-31 + P4M should be 2025-05-31 -> 2025-05-31
        # Let's be careful: Jan 31 -> Feb 28 (overflow) -> Mar 28 -> Apr 28 -> May 28
        # No wait, we apply all 4 months together: Jan -> May is 4 months, day 31 exists in May
        result = add_duration(datetime(2025, 1, 31), "P4M")
        assert result == datetime(2025, 5, 31)

    def test_negative_fractional_duration(self):
        result = add_duration(datetime(2025, 3, 10, 8, 0), "-PT0.5H")
        assert result == datetime(2025, 3, 10, 7, 30)
